data.value:
CREATE TABLE company_public_knowledge_operations (
 actor_id TEXT NOT NULL, company_id TEXT NOT NULL, operation TEXT NOT NULL, idempotency_key TEXT NOT NULL,
 request_hash TEXT NOT NULL, known_ticks BIGINT NOT NULL, payload TEXT NOT NULL, completed BOOLEAN NOT NULL DEFAULT FALSE,
 PRIMARY KEY(actor_id,company_id,operation,idempotency_key));
CREATE INDEX ix_public_knowledge_company_time ON company_public_knowledge_operations(company_id,known_ticks);
